/* Demonstrates using utimes() to set custom access and modification times. */
#include <stdio.h>
#include <stdlib.h>
#include <sys/time.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define FILENAME "custom_times_test.tmp"

int main() {
    // 1. Create a dummy file to operate on
    int fd = open(FILENAME, O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("Failed to create file");
        return EXIT_FAILURE;
    }
    close(fd);

    // 2. Define custom timestamps (using struct timeval for microsecond precision)
    struct timeval new_times[2];
    time_t current_sec = time(NULL);

    // new_times[0]: Access time (atime) set to 1 hour ago
    new_times[0].tv_sec = current_sec - 3600;
    new_times[0].tv_usec = 500000; // 500 milliseconds

    // new_times[1]: Modification time (mtime) set to 30 minutes ago
    new_times[1].tv_sec = current_sec - 1800;
    new_times[1].tv_usec = 0;

    // 3. Apply the custom timestamps using utimes
    if (utimes(FILENAME, new_times) == -1) {
        perror("utimes failed");
        unlink(FILENAME); 
        return EXIT_FAILURE;
    }

    // 4. Verify the changes (optional)
    struct stat st;
    if (stat(FILENAME, &st) == 0) {
        printf("Successfully set times for %s:\n", FILENAME);
        printf("  Access Time (s): %ld\n", (long)st.st_atime);
        printf("  Modification Time (s): %ld\n", (long)st.st_mtime);
    }

    // Cleanup
    unlink(FILENAME);
    return EXIT_SUCCESS;
}
